const toolCall = $input.first().json.body.message.toolCalls[0];
const args = toolCall.function['arguments'];

const startDateTime = new Date(`${args.date}T${args.time}:00`);
const endDateTime = new Date(startDateTime.getTime() + 30 * 60000);
const pad = n => String(n).padStart(2, '0');
const endTime = `${pad(endDateTime.getHours())}:${pad(endDateTime.getMinutes())}`;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const rawEmail = (args.email || "").toString().trim();
const validEmail = emailRegex.test(rawEmail) ? rawEmail : null;

// Normalize phone for WATI: full international format, digits only, no '+', no leading 0.
const DEFAULT_COUNTRY_CODE = "92"; // Pakistan
let whatsappNumber = (args.phone_number || "").toString().replace(/\D/g, "");
if (whatsappNumber.startsWith("00")) {
  // 00 international prefix -> drop it
  whatsappNumber = whatsappNumber.slice(2);
} else if (whatsappNumber.startsWith("0")) {
  // Local format with trunk 0 -> replace with country code
  whatsappNumber = DEFAULT_COUNTRY_CODE + whatsappNumber.slice(1);
} else if (!whatsappNumber.startsWith(DEFAULT_COUNTRY_CODE)) {
  // Bare local number without trunk 0 or country code -> prepend country code
  whatsappNumber = DEFAULT_COUNTRY_CODE + whatsappNumber;
}
const hasValidPhone = whatsappNumber.length >= 11;

return [{
  json: {
    toolCallId: toolCall.id,
    patient_name: args.patient_name,
    phone_number: args.phone_number,
    whatsapp_number: whatsappNumber,
    has_valid_phone: hasValidPhone,
    service_type: args.service_type,
    date: args.date,
    time: args.time,
    end_time: endTime,
    email: validEmail,
    has_valid_email: validEmail !== null
  }
}];
